  showToast('Presupuesto PDF generado correctamente');
}

function sendQuoteEmail() {
  showToast(' Presupuesto enviado por email al cliente');
}

function exportBillingExcel() {
  let csv = 'Factura,Cliente,Fecha,Vencimiento,Base,IVA,Total,Estado\n';
  DB.invoices.forEach(inv => {
    csv += `${inv.num},${inv.client},${inv.date},${inv.due},${inv.base},${inv.tax},${inv.total},${inv.status}\n`;
  });
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'facturas_fazluiz3d.csv';
  a.click();
  showToast('📊 Exportado a CSV/Excel');
}

// ==================== AI COMMERCIAL ====================
function sendAICommercial() {
  const input = document.getElementById('aiCommercialInput');
  const msg = input.value.trim();
  if (!msg) return;

  const container = document.getElementById('aiCommercialMessages');

  // User message
  container.innerHTML += `
    <div class="ai-message user">
      <div class="ai-avatar">👤</div>
      <div class="ai-bubble">${msg}</div>
    </div>
  `;

  input.value = '';

  // Simulated AI response
  setTimeout(() => {
    const responses = [
      `He analizado la empresa mencionada. Aquí tienes un email personalizado:<br><br><strong>Asunto:</strong> Solución de impresión 3D para [Empresa]<br><br>Estimado/a,<br><br>He revisado su perfil empresarial y veo oportunidades claras para optimizar su cadena de producción con impresión 3D industrial. En FazLuiz 3D podemos:<br>• Reducir tiempos de prototipado en 60%<br>• Eliminar costes de moldes para series cortas<br>• Ofrecer materiales técnicos certificados<br><br>¿Le interesaría una demostración sin compromiso?<br><br>Saludos,<br>Thiago Luiz — FazLuiz 3D`,
      `📊 <strong>Análisis de oportunidad:</strong><br><br>• Tamaño empresa: Mediana (50-200 empleados)<br>• Sector: Alta demanda de prototipos<br>• Competencia usando 3D: 3 empresas similares ya lo hacen<br>• Presupuesto estimado: €5,000-15,000/año<br>• Probabilidad de conversión: 45%<br><br>🎯 <strong>Recomendación:</strong> Contactar esta semana con propuesta personalizada enfocada en reducción de costes.`,
      `💼 <strong>Mensaje LinkedIn generado:</strong><br><br>"Hola [Nombre], he visto que [Empresa] está creciendo rápidamente en el sector [X]. Muchas empresas de su tamaño están usando impresión 3D para acelerar su I+D. En FazLuiz 3D ayudamos a reducir el time-to-market de prototipos en un 60%. ¿Tiene 15 minutos esta semana para una breve llamada?"<br><br>📈 Tasa de respuesta estimada: 35%`
    ];

    const response = responses[Math.floor(Math.random() * responses.length)];
    container.innerHTML += `
      <div class="ai-message bot">
        <div class="ai-avatar">🤖</div>
        <div class="ai-bubble">${response}</div>
      </div>
    `;
    container.scrollTop = container.scrollHeight;
  }, 1000);

  container.scrollTop = container.scrollHeight;
}

// ==================== STL ANALYSIS ====================
function analyzeSTL(input) {
  if (input.files && input.files[0]) {
    const fileName = input.files[0].name;
    document.getElementById('stlUploadZone').innerHTML = `
      <div class="upload-zone-icon">✅</div>
      <div style="font-size:16px;font-weight:500;margin-bottom:8px">${fileName}</div>
      <div style="font-size:13px;color:var(--cyan-holo)">Analizando modelo...</div>
    `;

    setTimeout(() => {
      document.getElementById('stlAnalysisResult').style.display = 'block';

      // Random values for demo
      const volume = (30 + Math.random() * 50).toFixed(1);
      const weight = (volume * 1.25).toFixed(1);
      const hours = Math.floor(3 + Math.random() * 10);
      const mins = Math.floor(Math.random() * 60);
      const material = (weight * 1.1).toFixed(0);
      const cost = (weight * 0.35 + hours * 2.5).toFixed(2);
      const suggested = (cost * 1.6).toFixed(2);

      document.getElementById('stlVolume').textContent = volume + ' cm³';
      document.getElementById('stlWeight').textContent = weight + 'g (PLA)';
      document.getElementById('stlTime').textContent = hours + 'h ' + mins + 'min';
      document.getElementById('stlMaterial').textContent = material + 'g (+10% soporte)';
      document.getElementById('stlCost').textContent = '€' + cost;
      document.getElementById('stlSuggestedPrice').textContent = '€' + suggested;

      showToast('✅ Análisis STL completado');
    }, 2000);
  }
}

// ==================== MODALS ====================
function openModal(id) {
  document.getElementById(id).classList.add('active');
}

function closeModal(id) {
  document.getElementById(id).classList.remove('active');
}

// Close modal on overlay click
document.querySelectorAll('.modal-overlay').forEach(overlay => {
  overlay.addEventListener('click', function(e) {
    if (e.target === this) {
      this.classList.remove('active');
    }
  });
});

// ==================== TOAST ====================
function showToast(message, icon = '✅') {
  const toast = document.getElementById('toast');
  document.getElementById('toastMessage').textContent = message;
  document.getElementById('toastIcon').textContent = icon;
  toast.classList.add('active');
  setTimeout(() => toast.classList.remove('active'), 3000);
}

// ==================== BACKUP ====================
function doBackup() {
  showToast('💾 Backup completado — 24.5 MB guardado', '💾');
}

// ==================== CHARTS ====================
function initCharts() {
  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { labels: { color: '#94A3B8', font: { size: 11 } } }
    },
    scales: {
      x: { ticks: { color: '#64748B' }, grid: { color: 'rgba(34,211,238,0.05)' } },
      y: { ticks: { color: '#64748B' }, grid: { color: 'rgba(34,211,238,0.05)' } }
    }
  };

  // Revenue Chart
  new Chart(document.getElementById('chartRevenue'), {
    type: 'line',
    data: {
      labels: ['Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul'],
      datasets: [{
        label: 'Ingresos',
        data: [8200, 9100, 7800, 10500, 11200, 12450],
        borderColor: '#2D7FF9',
        backgroundColor: 'rgba(45,127,249,0.1)',
        fill: true,
        tension: 0.4
      }, {
        label: 'Gastos',
        data: [5100, 5400, 4900, 6200, 6100, 7630],
        borderColor: '#EF4444',
        backgroundColor: 'rgba(239,68,68,0.1)',
        fill: true,
        tension: 0.4
      }]
    },
    options: chartOptions
  });

  // Materials Chart
  new Chart(document.getElementById('chartMaterials'), {
    type: 'doughnut',
    data: {
      labels: ['PLA', 'PETG', 'ABS', 'Resina', 'TPU'],
      datasets: [{
        data: [45, 20, 15, 12, 8],
        backgroundColor: ['#2D7FF9', '#22D3EE', '#10B981', '#F59E0B', '#EF4444'],
        borderWidth: 0
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { color: '#94A3B8', padding: 16 } }
      }
    }
  });

  // Order Status Chart
  new Chart(document.getElementById('chartOrderStatus'), {
    type: 'bar',
    data: {
      labels: ['Completados', 'En producción', 'Diseño', 'Pendientes'],
      datasets: [{
        label: 'Pedidos',
        data: [142, 8, 3, 5],
        backgroundColor: ['#10B981', '#F59E0B', '#2D7FF9', '#22D3EE'],
        borderRadius: 8
      }]
    },
    options: chartOptions
  });

  // Profit Chart
  new Chart(document.getElementById('chartProfit'), {
    type: 'line',
    data: {
      labels: ['Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul'],
      datasets: [{
        label: 'Beneficio',
        data: [3100, 3700, 2900, 4300, 5100, 4820],
        borderColor: '#10B981',
        backgroundColor: 'rgba(16,185,129,0.1)',
        fill: true,
        tension: 0.4
      }]
    },
    options: chartOptions
  });

  // Billing Chart
  new Chart(document.getElementById('chartBilling'), {
    type: 'bar',
    data: {
      labels: ['Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul'],
      datasets: [{
        label: 'Ingresos',
        data: [8200, 9100, 7800, 10500, 11200, 12450],
        backgroundColor: 'rgba(45,127,249,0.6)',
        borderRadius: 6
      }, {
        label: 'Gastos',
        data: [5100, 5400, 4900, 6200, 6100, 7630],
        backgroundColor: 'rgba(239,68,68,0.6)',
        borderRadius: 6
      }]
    },
    options: chartOptions
  });

  // Payments Chart
  new Chart(document.getElementById('chartPayments'), {
    type: 'doughnut',
    data: {
      labels: ['Cobrado', 'Pendiente', 'Vencido'],
      datasets: [{
        data: [9250, 3200, 450],
        backgroundColor: ['#10B981', '#F59E0B', '#EF4444'],
        borderWidth: 0
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { color: '#94A3B8', padding: 16 } }
      }
    }
  });

  // Prediction Chart
  new Chart(document.getElementById('chartPrediction'), {
    type: 'line',
    data: {
      labels: ['Ago', 'Sep', 'Oct', 'Nov', 'Dic', 'Ene'],
      datasets: [{
        label: 'Predicción IA',
        data: [13200, 14100, 13800, 15200, 16800, 14500],
        borderColor: '#22D3EE',
        backgroundColor: 'rgba(34,211,238,0.1)',
        fill: true,
        tension: 0.4,
        borderDash: [5, 5]
      }, {
        label: 'Histórico',
        data: [12450, 11200, 10500, 9800, 11000, 12000],
        borderColor: '#2D7FF9',
        backgroundColor: 'rgba(45,127,249,0.1)',
        fill: true,
        tension: 0.4
      }]
    },
    options: chartOptions
  });
}

// ==================== QUOTE LINES ====================
let quoteLineCount = 1;
function addQuoteLine() {
  quoteLineCount++;
  const container = document.getElementById('quoteLines');
  const div = document.createElement('div');
  div.className = 'form-row';
  div.style.alignItems = 'end';
  div.innerHTML = `
    <div class="form-group" style="flex:2">
      <input type="text" class="form-input" placeholder="Descripción..." id="qDesc${quoteLineCount}">
    </div>
    <div class="form-group">
      <input type="number" class="form-input" value="1" id="qQty${quoteLineCount}" oninput="updateQuoteTotal()">
    </div>
    <div class="form-group">
      <input type="number" class="form-input" value="0" id="qPrice${quoteLineCount}" oninput="updateQuoteTotal()">
    </div>
    <div class="form-group">
      <input type="text" class="form-input" value="€0.00" readonly id="qTotal${quoteLineCount}">
    </div>
  `;
  container.appendChild(div);
}

function updateQuoteTotal() {
  let subtotal = 0;
  for (let i = 1; i <= quoteLineCount; i++) {
    const qty = parseFloat(document.getElementById('qQty' + i)?.value) || 0;
    const price = parseFloat(document.getElementById('qPrice' + i)?.value) || 0;
    const total = qty * price;
    const totalEl = document.getElementById('qTotal' + i);
    if (totalEl) totalEl.value = '€' + total.toFixed(2);
    subtotal += total;
  }
  const iva = subtotal * 0.21;
  const total = subtotal + iva;
  document.getElementById('quoteSubtotal').textContent = '€' + subtotal.toFixed(2);
  document.getElementById('quoteIVA').textContent = '€' + iva.toFixed(2);
  document.getElementById('quoteTotal').textContent = '€' + total.toFixed(2);
}

// ==================== INIT ====================
function initApp() {
  renderClients();
  renderOrders();
  renderInventory();
  renderCalendar();
  renderInvoices();
  calculate3D();
  initCharts();
}

// Auto-login for demo
// doLogin();
</script>
</body>
</html>
```

