}

.badge-success { background: rgba(16, 185, 129, 0.15); color: var(--success); }
.badge-warning { background: rgba(245, 158, 11, 0.15); color: var(--warning); }
.badge-danger { background: rgba(239, 68, 68, 0.15); color: var(--danger); }
.badge-info { background: rgba(45, 127, 249, 0.15); color: var(--blue-electric); }
.badge-cyan { background: rgba(34, 211, 238, 0.15); color: var(--cyan-holo); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  font-family: var(--font-body);
}

.btn-primary {
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  color: white;
}

.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: var(--glow-blue);
}

.btn-secondary {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  color: var(--white);
}

.btn-secondary:hover {
  border-color: var(--cyan-holo);
}

.btn-danger {
  background: rgba(239, 68, 68, 0.15);
  color: var(--danger);
}

.btn-sm {
  padding: 6px 14px;
  font-size: 12px;
}

/* Forms */
.form-group {
  margin-bottom: 16px;
}

.form-label {
  display: block;
  font-size: 13px;
  font-weight: 500;
  margin-bottom: 6px;
  color: var(--gray-light);
}

.form-input, .form-select, .form-textarea {
  width: 100%;
  padding: 12px 16px;
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  color: var(--white);
  font-size: 14px;
  font-family: var(--font-body);
  transition: all 0.3s;
}

.form-input:focus, .form-select:focus, .form-textarea:focus {
  outline: none;
  border-color: var(--cyan-holo);
  box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.1);
}

.form-textarea {
  resize: vertical;
  min-height: 80px;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: none;
  align-items: center;
  justify-content: center;
}

.modal-overlay.active {
  display: flex;
}

.modal {
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: 20px;
  padding: 32px;
  width: 560px;
  max-width: 90vw;
  max-height: 85vh;
  overflow-y: auto;
  box-shadow: var(--glow-blue);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

.modal-header h2 {
  font-family: var(--font-title);
  font-size: 20px;
}

.modal-close {
  width: 36px; height: 36px;
  background: rgba(239, 68, 68, 0.1);
  border: none;
  border-radius: 8px;
  color: var(--danger);
  font-size: 18px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Calculator */
.calc-result {
  background: linear-gradient(135deg, rgba(45, 127, 249, 0.1), rgba(34, 211, 238, 0.1));
  border: 1px solid var(--glass-border);
  border-radius: 16px;
  padding: 24px;
  margin-top: 20px;
}

.calc-result-value {
  font-family: var(--font-title);
  font-size: 36px;
  font-weight: 700;
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Progress Bar */
.progress-bar {
  height: 6px;
  background: rgba(34, 211, 238, 0.1);
  border-radius: 3px;
  overflow: hidden;
  margin-top: 8px;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--blue-electric), var(--cyan-holo));
  border-radius: 3px;
  transition: width 0.5s ease;
}

/* Chart Container */
.chart-container {
  position: relative;
  height: 300px;
}

/* Pipeline */
.pipeline {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 16px;
}

.pipeline-column {
  min-width: 280px;
  background: rgba(15, 23, 42, 0.3);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  padding: 16px;
}

.pipeline-column-title {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pipeline-card {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  padding: 14px;
  margin-bottom: 10px;
  cursor: pointer;
  transition: all 0.2s;
}

.pipeline-card:hover {
  border-color: var(--cyan-holo);
  transform: translateY(-1px);
}

.pipeline-card-title {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 4px;
}

.pipeline-card-value {
  font-size: 12px;
  color: var(--cyan-holo);
  font-weight: 600;
}

/* Calendar */
.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
}

.calendar-header-cell {
  text-align: center;
  font-size: 11px;
  color: var(--gray-titanium);
  padding: 8px;
  font-weight: 600;
  text-transform: uppercase;
}

.calendar-cell {
  aspect-ratio: 1;
  background: rgba(15, 23, 42, 0.3);
  border: 1px solid var(--glass-border);
  border-radius: 8px;
  padding: 6px;
  font-size: 12px;
  cursor: pointer;
  transition: all 0.2s;
  position: relative;
}

.calendar-cell:hover {
