  background: rgba(45, 127, 249, 0.1);
}

.calendar-cell.has-event::after {
  content: '';
  position: absolute;
  bottom: 4px; left: 50%;
  transform: translateX(-50%);
  width: 6px; height: 6px;
  background: var(--cyan-holo);
  border-radius: 50%;
}

/* STL Upload Zone */
.upload-zone {
  border: 2px dashed var(--glass-border);
  border-radius: 16px;
  padding: 48px;
  text-align: center;
  cursor: pointer;
  transition: all 0.3s;
}

.upload-zone:hover {
  border-color: var(--cyan-holo);
  background: rgba(34, 211, 238, 0.03);
}

.upload-zone-icon {
  font-size: 48px;
  margin-bottom: 16px;
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 20px;
  background: rgba(15, 23, 42, 0.3);
  border-radius: 12px;
  padding: 4px;
  overflow-x: auto;
}

.tab {
  padding: 10px 20px;
  border-radius: 8px;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
  color: var(--gray-light);
}

.tab.active {
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  color: white;
  font-weight: 500;
}

/* Notification Toast */
.toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  padding: 16px 24px;
  z-index: 2000;
  display: none;
  align-items: center;
  gap: 12px;
  box-shadow: var(--glow-blue);
  animation: slideIn 0.3s ease;
}

.toast.active { display: flex; }

@keyframes slideIn {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--glass-border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--cyan-holo); }

/* Hamburger */
.hamburger {
  display: none;
  position: fixed;
  top: 16px; left: 16px;
  z-index: 200;
  width: 40px; height: 40px;
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 20px;
  color: var(--white);
}

@media (max-width: 768px) {
  .hamburger { display: flex; }
}

/* Inventory Alert */
.alert-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: rgba(239, 68, 68, 0.05);
  border: 1px solid rgba(239, 68, 68, 0.2);
  border-radius: 10px;
  margin-bottom: 8px;
}

.alert-item.warning {
  background: rgba(245, 158, 11, 0.05);
  border-color: rgba(245, 158, 11, 0.2);
}

/* Kanban */
.kanban-board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 20px;
}

.kanban-col {
  min-width: 300px;
  flex: 1;
}

.kanban-col-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: rgba(15, 23, 42, 0.4);
  border-radius: 12px 12px 0 0;
  border: 1px solid var(--glass-border);
  border-bottom: none;
}

.kanban-col-body {
  background: rgba(15, 23, 42, 0.2);
  border: 1px solid var(--glass-border);
  border-radius: 0 0 12px 12px;
  padding: 12px;
  min-height: 400px;
}

.kanban-item {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  padding: 14px;
  margin-bottom: 10px;
  cursor: grab;
  transition: all 0.2s;
}

.kanban-item:hover {
  border-color: var(--cyan-holo);
}

/* Maintenance Log */
.maintenance-item {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 16px;
  border-bottom: 1px solid var(--glass-border);
}

.maintenance-dot {
  width: 12px; height: 12px;
  border-radius: 50%;
  background: var(--cyan-holo);
  margin-top: 4px;
  flex-shrink: 0;
}

/* Search */
.search-box {
  position: relative;
  margin-bottom: 20px;
}

.search-box input {
  width: 100%;
  padding: 12px 16px 12px 44px;
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  color: var(--white);
  font-size: 14px;
}

.search-box input:focus {
  outline: none;
  border-color: var(--cyan-holo);
}

.search-box .search-icon {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-titanium);
}

/* AI Chat */
.ai-chat-container {
  height: 400px;
  display: flex;
  flex-direction: column;
}

.ai-messages {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  background: rgba(15, 23, 42, 0.3);
  border-radius: 12px;
  margin-bottom: 16px;
}

.ai-message {
  margin-bottom: 16px;
  display: flex;
  gap: 12px;
}

.ai-message.user {
  flex-direction: row-reverse;
}

.ai-avatar {
  width: 36px; height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.ai-message.bot .ai-avatar {
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
}

.ai-message.user .ai-avatar {
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
}

.ai-bubble {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  padding: 12px 16px;
  font-size: 14px;
  max-width: 70%;
  line-height: 1.5;
}

.ai-input-row {
  display: flex;
  gap: 8px;
}

.ai-input-row input {
  flex: 1;
  padding: 12px 16px;
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  color: var(--white);
  font-size: 14px;
}

.ai-input-row input:focus {
  outline: none;
  border-color: var(--cyan-holo);
}

/* Responsive tables */
