// ==================== CALENDAR ====================
function renderCalendar() {
  const grid = document.getElementById('calendarGrid');
  const months = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  const days = ['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];

  document.getElementById('calendarMonth').textContent = months[currentMonth] + ' ' + currentYear;

  let html = days.map(d => `<div class="calendar-header-cell">${d}</div>`).join('');

  const firstDay = new Date(currentYear, currentMonth, 1).getDay();
  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  const today = new Date();
  const eventDays = [3, 7, 10, 12, 15, 18, 22, 25, 28];

  // Adjust for Monday start
  const startOffset = firstDay === 0 ? 6 : firstDay - 1;

  for (let i = 0; i < startOffset; i++) {
    html += '<div class="calendar-cell" style="opacity:0.3"></div>';
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const isToday = d === today.getDate() && currentMonth === today.getMonth() && currentYear === today.getFullYear();
    const hasEvent = eventDays.includes(d);
    html += `<div class="calendar-cell ${isToday ? 'today' : ''} ${hasEvent ? 'has-event' : ''}" onclick="showToast('Día ${d} — ${hasEvent ? 'Hay eventos programados' : 'Sin eventos'}')">${d}</div>`;
  }

  grid.innerHTML = html;
}

function changeMonth(dir) {
  currentMonth += dir;
  if (currentMonth > 11) { currentMonth = 0; currentYear++; }
  if (currentMonth < 0) { currentMonth = 11; currentYear--; }
  renderCalendar();
}

