# FazLuiz 3D — Plataforma SaaS Universal

Aquí tienes la plataforma completa, limpia y universal:

```html
<!DOCTYPE html>
<html lang="es" data-theme="dark">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>FazLuiz 3D — Plataforma SaaS Universal</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">
<script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.0/chart.umd.min.js"></script>
<style>
/* ============================================
   FAZLUIZ 3D - UNIVERSAL STYLESHEET
   Clean, Modern, Glassmorphism Design
   ============================================ */

:root {
  /* Color System */
  --bg-primary: #0F172A;
  --bg-secondary: #1E293B;
  --bg-tertiary: #334155;
  --bg-card: rgba(30, 41, 59, 0.6);
  --bg-glass: rgba(15, 23, 42, 0.7);

  --blue-electric: #2D7FF9;
  --blue-dark: #1E40AF;
  --cyan-holo: #22D3EE;
  --cyan-light: #67E8F9;
  --white: #F8FAFC;
  --gray-100: #F1F5F9;
  --gray-200: #E2E8F0;
  --gray-300: #CBD5E1;
  --gray-400: #94A3B8;
  --gray-500: #64748B;
  --gray-600: #475569;
  --gray-700: #334155;

  --success: #10B981;
  --success-light: #34D399;
  --warning: #F59E0B;
  --warning-light: #FBBF24;
  --danger: #EF4444;
  --danger-light: #F87171;
  --info: #3B82F6;

  /* Glass Effects */
  --glass-bg: rgba(30, 41, 59, 0.4);
  --glass-border: rgba(34, 211, 238, 0.15);
  --glass-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  --glow-blue: 0 0 20px rgba(45, 127, 249, 0.3);
  --glow-cyan: 0 0 20px rgba(34, 211, 238, 0.3);

  /* Typography */
  --font-title: 'Space Grotesk', -apple-system, sans-serif;
  --font-body: 'Inter', -apple-system, sans-serif;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  /* Transitions */
  --transition-fast: 0.15s ease;
  --transition-normal: 0.3s ease;
  --transition-slow: 0.5s ease;
}

[data-theme="light"] {
  --bg-primary: #F8FAFC;
  --bg-secondary: #F1F5F9;
  --bg-tertiary: #E2E8F0;
  --bg-card: rgba(255, 255, 255, 0.8);
  --bg-glass: rgba(255, 255, 255, 0.7);
  --glass-bg: rgba(255, 255, 255, 0.6);
  --glass-border: rgba(45, 127, 249, 0.2);
  --glass-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
  --white: #0F172A;
  --gray-400: #64748B;
  --gray-500: #475569;
}

/* ============================================
   RESET & BASE
   ============================================ */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--white);
  min-height: 100vh;
  line-height: 1.6;
  overflow-x: hidden;
}

/* ============================================
   BACKGROUND EFFECTS
   ============================================ */
.bg-grid {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: 
    radial-gradient(ellipse at 20% 50%, rgba(45, 127, 249, 0.08) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 20%, rgba(34, 211, 238, 0.06) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 80%, rgba(45, 127, 249, 0.04) 0%, transparent 50%);
  z-index: 0;
  pointer-events: none;
}

.bg-grid::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: 
    linear-gradient(rgba(34, 211, 238, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(34, 211, 238, 0.03) 1px, transparent 1px);
  background-size: 50px 50px;
}

/* ============================================
   SCROLLBAR
   ============================================ */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--glass-border);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--cyan-holo);
}

/* ============================================
   LOGIN SCREEN
   ============================================ */
.login-screen {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10000;
  background: var(--bg-primary);
}

.login-container {
  background: var(--glass-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  width: 420px;
  max-width: 90vw;
  text-align: center;
  box-shadow: var(--glow-blue);
  animation: fadeIn 0.5s ease;
}

.login-logo {
  width: 80px;
  height: 80px;
  margin: 0 auto var(--space-lg);
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  font-weight: 700;
  font-family: var(--font-title);
  color: white;
  box-shadow: var(--glow-cyan);
}

.login-container h1 {
  font-family: var(--font-title);
  font-size: 28px;
  margin-bottom: var(--space-sm);
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.login-container p {
  color: var(--gray-400);
  margin-bottom: var(--space-xl);
  font-size: 14px;
}

/* ============================================
   FORM ELEMENTS
   ============================================ */
.form-input, .form-select, .form-textarea {
  width: 100%;
  padding: 12px 16px;
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  color: var(--white);
  font-size: 14px;
  font-family: var(--font-body);
  transition: all var(--transition-normal);
}

.form-input:focus, .form-select:focus, .form-textarea:focus {
  outline: none;
  border-color: var(--cyan-holo);
  box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.1);
}

.form-input::placeholder {
  color: var(--gray-500);
}

.form-label {
  display: block;
  font-size: 13px;
  font-weight: 500;
  margin-bottom: var(--space-sm);
  color: var(--gray-400);
}

.form-group {
  margin-bottom: var(--space-md);
}

.form-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-md);
}

/* ============================================
   BUTTONS
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-normal);
  border: none;
  font-family: var(--font-body);
  white-space: nowrap;
  text-decoration: none;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-primary {
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  color: white;
  box-shadow: 0 4px 12px rgba(45, 127, 249, 0.3);
}

.btn-primary:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(45, 127, 249, 0.4);
}

.btn-secondary {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  color: var(--white);
}

.btn-secondary:hover:not(:disabled) {
  border-color: var(--cyan-holo);
  background: rgba(34, 211, 238, 0.1);
}

.btn-danger {
  background: rgba(239, 68, 68, 0.15);
  color: var(--danger);
  border: 1px solid rgba(239, 68, 68, 0.3);
}

.btn-danger:hover:not(:disabled) {
  background: rgba(239, 68, 68, 0.25);
}

.btn-success {
  background: rgba(16, 185, 129, 0.15);
  color: var(--success);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.btn-sm {
  padding: 6px 14px;
  font-size: 12px;
}

.btn-lg {
  padding: 14px 28px;
  font-size: 16px;
}

.btn-icon {
  width: 40px;
  height: 40px;
  padding: 0;
}

/* ============================================
   LAYOUT
   ============================================ */
.app-container {
  display: none;
  min-height: 100vh;
  position: relative;
  z-index: 1;
}

.app-container.active {
  display: flex;
}

/* Sidebar */
.sidebar {
  width: 280px;
  min-height: 100vh;
  background: var(--glass-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-right: 1px solid var(--glass-border);
  padding: var(--space-lg) var(--space-md);
  position: fixed;
  left: 0;
  top: 0;
  z-index: 100;
  overflow-y: auto;
  transition: transform var(--transition-normal);
}

.sidebar-logo {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-sm) var(--space-md);
  margin-bottom: var(--space-xl);
}

.sidebar-logo-icon {
  width: 44px;
  height: 44px;
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 18px;
  color: white;
  font-family: var(--font-title);
  flex-shrink: 0;
}

.sidebar-logo-text h2 {
  font-family: var(--font-title);
  font-size: 16px;
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.sidebar-logo-text span {
  font-size: 11px;
  color: var(--gray-400);
}

.nav-section {
  margin-bottom: var(--space-lg);
}

.nav-section-title {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--gray-500);
  padding: 0 var(--space-md);
  margin-bottom: var(--space-sm);
  font-weight: 600;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: 11px var(--space-md);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all var(--transition-fast);
  font-size: 14px;
  color: var(--gray-400);
  margin-bottom: 2px;
  position: relative;
}

.nav-item:hover {
  background: rgba(34, 211, 238, 0.08);
  color: var(--white);
}

.nav-item.active {
  background: rgba(45, 127, 249, 0.15);
  color: var(--cyan-holo);
  border: 1px solid rgba(34, 211, 238, 0.2);
}

.nav-item.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 20px;
  background: var(--cyan-holo);
  border-radius: 0 3px 3px 0;
}

.nav-icon {
  width: 20px;
  text-align: center;
  font-size: 16px;
}

.nav-badge {
  margin-left: auto;
  background: var(--blue-electric);
  color: white;
  font-size: 10px;
  padding: 2px 7px;
  border-radius: 10px;
  font-weight: 600;
}

/* Main Content */
.main-content {
  margin-left: 280px;
  flex: 1;
  padding: var(--space-lg) var(--space-xl);
  min-height: 100vh;
}

/* Top Bar */
.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-xl);
  padding-bottom: var(--space-md);
  border-bottom: 1px solid var(--glass-border);
}

.top-bar-left h1 {
  font-family: var(--font-title);
  font-size: 24px;
  font-weight: 600;
}

.top-bar-left p {
  color: var(--gray-400);
  font-size: 13px;
  margin-top: var(--space-xs);
}

.top-bar-right {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.top-btn {
  width: 40px;
  height: 40px;
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--gray-400);
  font-size: 18px;
  transition: all var(--transition-fast);
  position: relative;
}

.top-btn:hover {
  border-color: var(--cyan-holo);
  color: var(--cyan-holo);
}

.top-btn .notif-dot {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 8px;
  height: 8px;
  background: var(--danger);
  border-radius: 50%;
}

.user-avatar {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 14px;
  color: white;
  cursor: pointer;
}

/* ============================================
   CARDS & CONTAINERS
   ============================================ */
.card {
  background: var(--glass-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  margin-bottom: var(--space-md);
  transition: all var(--transition-normal);
  position: relative;
}

.card:hover {
  border-color: rgba(34, 211, 238, 0.3);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.card-title {
  font-family: var(--font-title);
  font-size: 16px;
  font-weight: 600;
}

.card-subtitle {
  font-size: 12px;
  color: var(--gray-400);
  margin-top: var(--space-xs);
}

/* Stats Grid */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--space-md);
  margin-bottom: var(--space-lg);
}

.stat-card {
  background: var(--glass-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  position: relative;
  overflow: hidden;
  transition: all var(--transition-normal);
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--glow-blue);
}

.stat-card::after {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 80px;
  height: 80px;
  background: radial-gradient(circle, rgba(34, 211, 238, 0.1) 0%, transparent 70%);
  border-radius: 50%;
}

.stat-label {
  font-size: 12px;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: var(--space-sm);
}

.stat-value {
  font-family: var(--font-title);
  font-size: 28px;
  font-weight: 700;
  background: linear-gradient(135deg, var(--white), var(--cyan-holo));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.stat-change {
  font-size: 12px;
  margin-top: var(--space-sm);
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.stat-change.positive { color: var(--success); }
.stat-change.negative { color: var(--danger); }

/* Grid Layouts */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-md);
}

/* ============================================
   TABLES
   ============================================ */
.table-responsive {
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  padding: 12px 16px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gray-500);
  border-bottom: 1px solid var(--glass-border);
  font-weight: 600;
}

.data-table td {
  padding: 14px 16px;
  font-size: 14px;
  border-bottom: 1px solid rgba(34, 211, 238, 0.05);
}

.data-table tr:hover td {
  background: rgba(34, 211, 238, 0.03);
}

/* ============================================
   BADGES
   ============================================ */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
}

.badge-success { 
  background: rgba(16, 185, 129, 0.15); 
  color: var(--success); 
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.badge-warning { 
  background: rgba(245, 158, 11, 0.15); 
  color: var(--warning); 
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.badge-danger { 
  background: rgba(239, 68, 68, 0.15); 
  color: var(--danger); 
  border: 1px solid rgba(239, 68, 68, 0.3);
}

.badge-info { 
  background: rgba(59, 130, 246, 0.15); 
  color: var(--info); 
  border: 1px solid rgba(59, 130, 246, 0.3);
}

.badge-cyan { 
  background: rgba(34, 211, 238, 0.15); 
  color: var(--cyan-holo); 
  border: 1px solid rgba(34, 211, 238, 0.3);
}

/* ============================================
   MODALS
   ============================================ */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  z-index: 1000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: var(--space-md);
}

.modal-overlay.active {
  display: flex;
  animation: fadeIn 0.2s ease;
}

.modal {
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  width: 560px;
  max-width: 100%;
  max-height: 85vh;
  overflow-y: auto;
  box-shadow: var(--glow-blue);
  animation: slideUp 0.3s ease;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.modal-header h2 {
  font-family: var(--font-title);
  font-size: 20px;
}

.modal-close {
  width: 36px;
  height: 36px;
  background: rgba(239, 68, 68, 0.1);
  border: none;
  border-radius: var(--radius-sm);
  color: var(--danger);
  font-size: 18px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.modal-close:hover {
  background: rgba(239, 68, 68, 0.2);
}

/* ============================================
   PROGRESS BARS
   ============================================ */
.progress-bar {
  height: 6px;
  background: rgba(34, 211, 238, 0.1);
  border-radius: 3px;
  overflow: hidden;
  margin-top: var(--space-sm);
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--blue-electric), var(--cyan-holo));
  border-radius: 3px;
  transition: width var(--transition-slow);
}

/* ============================================
   CHART CONTAINERS
   ============================================ */
.chart-container {
  position: relative;
  height: 300px;
}

/* ============================================
   PIPELINE / KANBAN
   ============================================ */
.pipeline {
  display: flex;
  gap: var(--space-md);
  overflow-x: auto;
  padding-bottom: var(--space-md);
}

.pipeline-column {
  min-width: 280px;
  background: rgba(15, 23, 42, 0.3);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  padding: var(--space-md);
}

.pipeline-column-title {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: var(--space-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.pipeline-card {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  margin-bottom: var(--space-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.pipeline-card:hover {
  border-color: var(--cyan-holo);
  transform: translateY(-1px);
}

.pipeline-card-title {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: var(--space-xs);
}

.pipeline-card-value {
  font-size: 12px;
  color: var(--cyan-holo);
  font-weight: 600;
}

/* ============================================
   CALENDAR
   ============================================ */
.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
}

.calendar-header-cell {
  text-align: center;
  font-size: 11px;
  color: var(--gray-500);
  padding: 8px;
  font-weight: 600;
  text-transform: uppercase;
}

.calendar-cell {
  aspect-ratio: 1;
  background: rgba(15, 23, 42, 0.3);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-sm);
  padding: 6px;
  font-size: 12px;
  cursor: pointer;
  transition: all var(--transition-fast);
  position: relative;
}

.calendar-cell:hover {
  border-color: var(--cyan-holo);
}

.calendar-cell.today {
  border-color: var(--blue-electric);
  background: rgba(45, 127, 249, 0.1);
}

.calendar-cell.has-event::after {
  content: '';
  position: absolute;
  bottom: 4px;
  left: 50%;
  transform: translateX(-50%);
  width: 6px;
  height: 6px;
  background: var(--cyan-holo);
  border-radius: 50%;
}

/* ============================================
   UPLOAD ZONE
   ============================================ */
.upload-zone {
  border: 2px dashed var(--glass-border);
  border-radius: var(--radius-lg);
  padding: var(--space-2xl);
  text-align: center;
  cursor: pointer;
  transition: all var(--transition-normal);
}

.upload-zone:hover {
  border-color: var(--cyan-holo);
  background: rgba(34, 211, 238, 0.03);
}

.upload-zone-icon {
  font-size: 48px;
  margin-bottom: var(--space-md);
}

/* ============================================
   TABS
   ============================================ */
.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: var(--space-lg);
  background: rgba(15, 23, 42, 0.3);
  border-radius: var(--radius-md);
  padding: 4px;
  overflow-x: auto;
}

.tab {
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  cursor: pointer;
  transition: all var(--transition-fast);
  white-space: nowrap;
  color: var(--gray-400);
}

.tab.active {
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  color: white;
  font-weight: 500;
}

/* ============================================
   AI CHAT
   ============================================ */
.ai-chat-container {
  height: 400px;
  display: flex;
  flex-direction: column;
}

.ai-messages {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-md);
  background: rgba(15, 23, 42, 0.3);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-md);
}

.ai-message {
  margin-bottom: var(--space-md);
  display: flex;
  gap: var(--space-md);
}

.ai-message.user {
  flex-direction: row-reverse;
}

.ai-avatar {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.ai-message.bot .ai-avatar {
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
}

.ai-message.user .ai-avatar {
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
}

.ai-bubble {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  font-size: 14px;
  max-width: 70%;
  line-height: 1.6;
}

.ai-input-row {
  display: flex;
  gap: var(--space-sm);
}

.ai-input-row input {
  flex: 1;
  padding: 12px 16px;
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  color: var(--white);
  font-size: 14px;
}

.ai-input-row input:focus {
  outline: none;
  border-color: var(--cyan-holo);
}

/* ============================================
   CALCULATOR RESULT
   ============================================ */
.calc-result {
  background: linear-gradient(135deg, rgba(45, 127, 249, 0.1), rgba(34, 211, 238, 0.1));
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  margin-top: var(--space-lg);
}

.calc-result-value {
  font-family: var(--font-title);
  font-size: 36px;
  font-weight: 700;
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ============================================
   ALERTS
   ============================================ */
.alert-item {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  background: rgba(239, 68, 68, 0.05);
  border: 1px solid rgba(239, 68, 68, 0.2);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-sm);
}

.alert-item.warning {
  background: rgba(245, 158, 11, 0.05);
  border-color: rgba(245, 158, 11, 0.2);
}

/* ============================================
   MAINTENANCE LOG
   ============================================ */
.maintenance-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md);
  border-bottom: 1px solid var(--glass-border);
}

.maintenance-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--cyan-holo);
  margin-top: 4px;
  flex-shrink: 0;
}

/* ============================================
   SEARCH
   ============================================ */
.search-box {
  position: relative;
  margin-bottom: var(--space-lg);
}

.search-box input {
  width: 100%;
  padding: 12px 16px 12px 44px;
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  color: var(--white);
  font-size: 14px;
}

.search-box input:focus {
  outline: none;
  border-color: var(--cyan-holo);
}

.search-box .search-icon {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-500);
}

/* ============================================
   TOAST NOTIFICATIONS
   ============================================ */
.toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  padding: 16px 24px;
  z-index: 2000;
  display: none;
  align-items: center;
  gap: var(--space-md);
  box-shadow: var(--glow-blue);
  animation: slideIn 0.3s ease;
  max-width: 400px;
}

.toast.active {
  display: flex;
}

.toast-icon {
  font-size: 20px;
}

.toast-content {
  flex: 1;
}

.toast-title {
  font-weight: 600;
  font-size: 14px;
  margin-bottom: 2px;
}

.toast-message {
  font-size: 12px;
  color: var(--gray-400);
}

/* ============================================
   API CONFIG BANNER
   ============================================ */
.api-config-banner {
  background: linear-gradient(135deg, rgba(245, 158, 11, 0.1), rgba(239, 68, 68, 0.1));
  border: 1px solid rgba(245, 158, 11, 0.3);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  margin-bottom: var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
}

.api-config-banner.configured {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.1), rgba(34, 211, 238, 0.1));
  border-color: rgba(16, 185, 129, 0.3);
}

.api-status {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex: 1;
}

.api-status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--danger);
  box-shadow: 0 0 10px var(--danger);
}

.api-status-dot.active {
  background: var(--success);
  box-shadow: 0 0 10px var(--success);
}

/* ============================================
   AI ENHANCEMENT BADGE
   ============================================ */
.ai-enhancement-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  background: linear-gradient(135deg, var(--blue-electric), var(--cyan-holo));
  color: white;
  font-size: 10px;
  padding: 4px 10px;
  border-radius: 20px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* ============================================
   LOADING SPINNER
   ============================================ */
.ai-loading {
  display: inline-block;
  width: 20px;
  height: 20px;
  border: 2px solid rgba(34, 211, 238, 0.3);
  border-top-color: var(--cyan-holo);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ============================================
   HAMBURGER MENU
   ============================================ */
.hamburger {
  display: none;
  position: fixed;
  top: 16px;
  left: 16px;
  z-index: 200;
  width: 40px;
  height: 40px;
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 20px;
  color: var(--white);
}

/* ============================================
   ANIMATIONS
   ============================================ */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideUp {
  from { 
    opacity: 0; 
    transform: translateY(20px); 
  }
  to { 
    opacity: 1; 
    transform: translateY(0); 
  }
}

@keyframes slideIn {
  from { 
    transform: translateX(100%); 
    opacity: 0; 
  }
  to { 
    transform: translateX(0); 
    opacity: 1; 
  }
}

.page-section {
  display: none;
}

.page-section.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 1200px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .sidebar { 
    transform: translateX(-100%); 
  }
  .sidebar.open { 
    transform: translateX(0); 
  }
  .main-content { 
    margin-left: 0; 
    padding: var(--space-md); 
  }
  .grid-2, .grid-3, .grid-4 { 
    grid-template-columns: 1fr; 
  }
  .stats-grid { 
    grid-template-columns: 1fr; 
  }
  .hamburger { 
    display: flex; 
  }
  .pipeline {
    flex-direction: column;
  }
  .pipeline-column {
    min-width: 100%;
  }
}

@media (max-width: 480px) {
  .top-bar {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-md);
  }
  .top-bar-right {
    width: 100%;
    justify-content: flex-end;
  }
}

/* ============================================
